CREATE TABLE public.member (id uuid PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON public.member FROM anon, authenticated; GRANT SELECT ON public.member TO anon, authenticated; GRANT ALL ON public.member TO service_role; ALTER TABLE public.member ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES public.member(id), role text NOT NULL CHECK(role IN ('MEMBER','ADMIN')));
REVOKE ALL ON public.user_roles FROM anon, authenticated; GRANT SELECT ON public.user_roles TO anon, authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.movie (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, rating text NOT NULL CHECK(rating IN ('ALL','12','15','19')), running_minutes int NOT NULL CHECK(running_minutes>0), genre text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON public.movie FROM anon, authenticated; GRANT SELECT ON public.movie TO anon, authenticated; GRANT ALL ON public.movie TO service_role; ALTER TABLE public.movie ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.screen (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, block1_rows int NOT NULL DEFAULT 0 CHECK(block1_rows>=0), block1_cols int NOT NULL DEFAULT 0 CHECK(block1_cols=0 OR block1_cols>=2), block2_rows int NOT NULL DEFAULT 0 CHECK(block2_rows>=0), block2_cols int NOT NULL DEFAULT 0 CHECK(block2_cols=0 OR block2_cols>=2), block3_rows int NOT NULL DEFAULT 0 CHECK(block3_rows>=0), block3_cols int NOT NULL DEFAULT 0 CHECK(block3_cols=0 OR block3_cols>=2), created_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON public.screen FROM anon, authenticated; GRANT SELECT ON public.screen TO anon, authenticated; GRANT ALL ON public.screen TO service_role; ALTER TABLE public.screen ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.seat (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), screen_id uuid NOT NULL REFERENCES public.screen(id), block_no smallint NOT NULL CHECK(block_no IN(1,2,3)), row_index int NOT NULL CHECK(row_index>=1), row_label text NOT NULL, col_no int NOT NULL CHECK(col_no>=1), UNIQUE(screen_id,row_label,col_no));
REVOKE ALL ON public.seat FROM anon, authenticated; GRANT SELECT ON public.seat TO anon, authenticated; GRANT ALL ON public.seat TO service_role; ALTER TABLE public.seat ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.screening (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), movie_id uuid NOT NULL REFERENCES public.movie(id), screen_id uuid NOT NULL REFERENCES public.screen(id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, price int NOT NULL CHECK(price>0), created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at));
REVOKE ALL ON public.screening FROM anon, authenticated; GRANT SELECT ON public.screening TO anon, authenticated; GRANT ALL ON public.screening TO service_role; ALTER TABLE public.screening ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.booking (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_no text NOT NULL UNIQUE, member_id uuid NOT NULL REFERENCES public.member(id), screening_id uuid NOT NULL REFERENCES public.screening(id), status text NOT NULL CHECK(status IN('CONFIRMED','CANCELLED')), total_amount int NOT NULL CHECK(total_amount>=0), booked_at timestamptz NOT NULL DEFAULT now(), cancelled_at timestamptz, refund_amount int, UNIQUE(id,screening_id), CHECK((status='CONFIRMED' AND cancelled_at IS NULL AND refund_amount IS NULL) OR (status='CANCELLED' AND cancelled_at IS NOT NULL AND refund_amount IS NOT NULL AND refund_amount=total_amount)));
REVOKE ALL ON public.booking FROM anon, authenticated; GRANT SELECT ON public.booking TO anon, authenticated; GRANT ALL ON public.booking TO service_role; ALTER TABLE public.booking ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.booking_seat (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL, screening_id uuid NOT NULL, seat_id uuid NOT NULL REFERENCES public.seat(id), is_active boolean NOT NULL DEFAULT true, unit_price int NOT NULL CHECK(unit_price>=0), is_discounted boolean NOT NULL DEFAULT false, FOREIGN KEY(booking_id,screening_id) REFERENCES public.booking(id,screening_id));
REVOKE ALL ON public.booking_seat FROM anon, authenticated; GRANT SELECT ON public.booking_seat TO anon, authenticated; GRANT ALL ON public.booking_seat TO service_role; ALTER TABLE public.booking_seat ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX booking_seat_active_uq ON public.booking_seat(screening_id,seat_id) WHERE is_active;
CREATE SEQUENCE public.booking_no_seq; REVOKE ALL ON SEQUENCE public.booking_no_seq FROM anon, authenticated; GRANT ALL ON SEQUENCE public.booking_no_seq TO service_role;
CREATE FUNCTION public.row_label(p_index int) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE v_n int:=p_index; v_label text:=''; BEGIN IF v_n IS NULL OR v_n<1 THEN RAISE EXCEPTION 'ROW_INVALID: Row index must be positive.'; END IF; WHILE v_n>0 LOOP v_n:=v_n-1; v_label:=chr(65+v_n%26)||v_label; v_n:=v_n/26; END LOOP; RETURN v_label; END $$;
CREATE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND r.role='ADMIN') $$;
REVOKE ALL ON FUNCTION public.is_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_admin() TO anon,authenticated;
CREATE FUNCTION public.generate_seats(p_screen_id uuid) RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_screen public.screen%ROWTYPE; v_block int; v_rows int; v_cols int; v_offset int:=0; v_total int:=0; BEGIN SELECT sc.* INTO v_screen FROM public.screen sc WHERE sc.id=p_screen_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'SCREEN_NOT_FOUND: The screen does not exist.'; END IF; IF EXISTS(SELECT 1 FROM public.seat s WHERE s.screen_id=p_screen_id) THEN RAISE EXCEPTION 'SEATS_ALREADY_EXIST: This screen already has seats.'; END IF; FOR v_block IN 1..3 LOOP v_rows:=CASE v_block WHEN 1 THEN v_screen.block1_rows WHEN 2 THEN v_screen.block2_rows ELSE v_screen.block3_rows END; v_cols:=CASE v_block WHEN 1 THEN v_screen.block1_cols WHEN 2 THEN v_screen.block2_cols ELSE v_screen.block3_cols END; IF v_rows>0 AND v_cols>0 THEN INSERT INTO public.seat(screen_id,block_no,row_index,row_label,col_no) SELECT p_screen_id,v_block,r.n,public.row_label(r.n),v_offset+c.n FROM generate_series(1,v_rows) r(n) CROSS JOIN generate_series(1,v_cols) c(n); v_total:=v_total+v_rows*v_cols; v_offset:=v_offset+v_cols; END IF; END LOOP; RETURN v_total; END $$;
REVOKE ALL ON FUNCTION public.generate_seats(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_name text:=btrim(coalesce(NEW.raw_user_meta_data->>'name','')); BEGIN IF length(v_name)<1 OR length(v_name)>30 THEN RAISE EXCEPTION 'NAME_INVALID: Name must have 1 to 30 characters.'; END IF; INSERT INTO public.member(id,name,email) VALUES(NEW.id,v_name,NEW.email); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'MEMBER'); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.handle_new_user() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
CREATE POLICY member_read_own ON public.member FOR SELECT TO authenticated USING(id=(SELECT auth.uid()));
CREATE POLICY roles_read_own ON public.user_roles FOR SELECT TO authenticated USING(user_id=(SELECT auth.uid()));
CREATE POLICY movie_read_public ON public.movie FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY screen_read_public ON public.screen FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY seat_read_public ON public.seat FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY screening_read_public ON public.screening FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY booking_read_own ON public.booking FOR SELECT TO authenticated USING(member_id=(SELECT auth.uid()));
CREATE POLICY booking_seat_read_own ON public.booking_seat FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.booking b WHERE b.id=booking_id AND b.member_id=(SELECT auth.uid())));
CREATE INDEX seat_screen_idx ON public.seat(screen_id); CREATE INDEX screening_screen_time_idx ON public.screening(screen_id,starts_at); CREATE INDEX screening_movie_idx ON public.screening(movie_id); CREATE INDEX booking_member_idx ON public.booking(member_id); CREATE INDEX booking_screening_idx ON public.booking(screening_id); CREATE INDEX booking_seat_booking_idx ON public.booking_seat(booking_id,screening_id); CREATE INDEX booking_seat_seat_idx ON public.booking_seat(seat_id);